    const choices=settings.playlists.map((item,index)=>`${index+1}. ${item.name}（${item.songs?.length||0} 首）`).join('\n');
    const answer=ROOT.prompt?.(`输入歌单序号，或直接输入新歌单名称：\n${choices}`);if(!answer)return null;
