  function companionCardText(character){if(!character)return'没有选中角色。请作为温柔自然的陪听伙伴回应。';const data=character.data||{},fields=[['角色描述',character.description||data.description],['性格',character.personality||data.personality],['场景',character.scenario||data.scenario],['角色备注',character.creator_notes||data.creator_notes],['示例对话',character.mes_example||data.mes_example]];return fields.filter(([,value])=>String(value||'').trim()).map(([label,value])=>`${label}：${String(value).trim().slice(0,3000)}`).join('\n').slice(0,8000)||'请保持当前角色的身份、语气和关系设定。';}
  function companionInstruction(info=companionCharacter(),worldText=activeCompanionWorldText){const music=companionSongContext(),duo=settings.companionDuoMode?'双人模式已开启：你可以偶尔表达“想再听一次”或“这首不适合现在”，但只能提出建议，最终播放控制权属于用户。':'',preset=settings.companionPresetEnabled!==false?String(settings.companionPreset||DEFAULT_COMPANION_PRESET).trim():'';return`你正在“角色陪听”小窗里以 ${info.name} 的身份和用户线上聊天、一起听歌。先给出这个人此刻最自然的第一反应，默认一到两行，够用就停。普通和偶尔无聊都是正确答案。短回复通常不加句号，优先用空格、换行或自然逗号。严禁任何破折号、装饰性省略号、括号动作、场景调度和人物小传。不要为了展示角色、情绪或关系而增加内容。不要假装真的听到未提供的声音，不要写“作为AI”，不要输出角色名标签，不要解释规则。${duo}\n\n当前角色心情提示：${companionMood(info)}。它只能帮助选择反应方向，不能要求多写一句，也不要直接复述心情文字或覆盖角色卡中已经成立的情绪。\n当前播放：${music.song}\n当前歌词：${music.lyric||'暂时没有歌词'}\n\n角色卡摘要：\n${companionCardText(info.character)}${worldText?`\n\n本轮激活的世界书内容：\n${worldText}`:''}${preset?`\n\n内置人物与文风预设：\n${preset}`:''}`;}
