  function companionBookNamesFrom(value){if(value===undefined||value===null)return[];let parsed=value;try{parsed=JSON.parse(String(value));}catch{}return(Array.isArray(parsed)?parsed:[parsed]).map(name=>String(name||'').trim()).filter(Boolean);}
  async function companionAttachedBookNames(info=companionCharacter()){const names=[],primary=info.character?.data?.extensions?.world||info.character?.extensions?.world;if(primary)names.push(String(primary).trim());const execute=info.ctx?.executeSlashCommandsWithOptions;if(typeof execute==='function')for(const command of['/getcharbook type=all create=false','/getglobalbooks'])try{const result=await execute(command,{handleParserErrors:false,handleExecutionErrors:false});names.push(...companionBookNamesFrom(result?.pipe));}catch(error){console.warn(`[音乐播放器] 读取已挂载世界书失败：${command}`,error);}for(const option of DOC.querySelectorAll?.('#world_info option:checked')||[]){const name=String(option.value||option.textContent||'').trim();if(name)names.push(name);}return[...new Set(names.filter(Boolean))];}
  function companionWorldMatch(text,key,entry){const raw=String(key||'').trim();if(!raw)return false;const caseSensitive=entry?.caseSensitive===true,source=caseSensitive?String(text):String(text).toLocaleLowerCase(),needle=caseSensitive?raw:raw.toLocaleLowerCase();if(entry?.matchWholeWords!==true)return source.includes(needle);const escaped=needle.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');try{return new RegExp(`(^|[^\\p{L}\\p{N}_])${escaped}(?=$|[^\\p{L}\\p{N}_])`,'u').test(source);}catch{return source.includes(needle);}}
