  async function companionWorldText(info=companionCharacter()){const load=info.ctx?.loadWorldInfo;if(typeof load!=='function')return'';const names=await companionAttachedBookNames(info);if(!names.length)return'';const main=(info.ctx?.chat||[]).filter(message=>message&&String(message.mes||'').trim()).slice(-30).map(message=>String(message.mes).slice(0,2000)),privateChat=companionMessages(info).slice(-24).map(message=>String(message.content||'').slice(0,1800)),scan=[...main,...privateChat].join('\n');try{const parts=[];for(const name of names){const book=await load(name),entries=Object.values(book?.entries||{}).filter(entry=>companionWorldEntryActive(entry,scan)).sort((a,b)=>(Number(b.order)||0)-(Number(a.order)||0));for(const entry of entries)parts.push(`【世界书：${name}】\n${String(entry.content).trim()}`);}return[...new Set(parts)].join('\n\n').slice(0,12000);}catch(error){console.warn('[音乐播放器] 角色陪听世界书读取失败',error);return'';}}
  function companionEndpoint(value){const base=String(value||'').trim().replace(/\/+$/,'');if(!base)throw Error('请先在陪听窗设置中填写 API 地址');if(!/^https?:\/\//i.test(base))throw Error('API 地址必须以 http:// 或 https:// 开头');if(/\/chat\/completions$/i.test(base))return base;return/\/v1$/i.test(base)?`${base}/chat/completions`:`${base}/v1/chat/completions`;}
