  async function requestCustomCompanion(taskPrompt=''){const info=companionCharacter();if(!String(settings.companionModel||'').trim())throw Error('请先在陪听窗设置中填写或选择模型名');const recentChat=(info.ctx?.chat||[]).filter(message=>message&&!message.is_system&&String(message.mes||'').trim()).slice(-12).map(message=>({role:message.is_user?'user':'assistant',content:String(message.mes).slice(0,1800)})),privateChat=companionMessages(info).slice(-24).map(message=>({role:message.role==='assistant'?'assistant':'user',content:String(message.content||'').slice(0,1800)})),headers={'Content-Type':'application/json'},key=String(settings.companionApiKey||'').trim();if(key)headers.Authorization=`Bearer ${key}`;const messages=[{role:'system',content:companionInstruction(info)},...recentChat,...privateChat];if(taskPrompt)messages.push({role:'user',content:String(taskPrompt).slice(0,5000)});const response=await fetch(companionEndpoint(settings.companionApiUrl),{method:'POST',headers,body:JSON.stringify({model:String(settings.companionModel).trim(),messages,temperature:.85,max_tokens:Math.max(32,Math.min(4096,Number(settings.companionMaxTokens)||300)),stream:false})}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{};}catch{}if(!response.ok)throw Error(data?.error?.message||data?.message||`API 请求失败（${response.status}）`);const reply=normalizeCompanionReply(data?.choices?.[0]?.message?.content??data?.choices?.[0]?.text??data?.output_text??data?.response,info.name);if(!reply)throw Error('模型没有返回可显示的文字');return reply;}
