  async function runCompanionTask(prompt,{addToChat=false,tts=false}={}){if(companionBusy)return'';const info=companionCharacter(),request=++companionRequest;companionBusy=true;renderCompanionDialog();try{const reply=await generateCompanionReply(prompt);if(request!==companionRequest||disposed)return'';if(addToChat){const messages=companionMessages(info);messages.push({role:'assistant',content:reply.slice(0,8000),time:Date.now()});setCompanionMessages(messages,info);save();if(tts)await speakCompanionReply(reply,info);}return reply;}catch(error){console.warn('[音乐播放器] 陪听任务失败',error);toast('error',`角色陪听失败：${error.message}`);return'';}finally{if(request===companionRequest){companionBusy=false;renderCompanionDialog();}}}
  async function createCompanionTicket({automatic=false}={}){if(!current||companionBusy)return;if(automatic&&(settings.companionQuiet||!settings.companionAutoTicket))return;const song=strip(current),reply=await runCompanionTask(`刚听完《${song.title}》— ${song.artist}。请用一句不超过45字、符合角色身份的话写听后评价，只输出评价本身。`);if(!reply)return;const list=companionTicketList();list.unshift({song,quote:reply.slice(0,180),time:Date.now()});if(list.length>30)list.length=30;save();if(!automatic){showCompanionTickets();toast('success','听后票根已生成');}}
  function isCompanionSongRequest(text){const value=String(text||'').replace(/\s+/g,'');if(!value||/(?:不想|不要|别|不用)(?:换|切|播|放|点|推荐)/.test(value))return false;return/(?:给我|帮我|可以|能不能|想|要|再)?(?:点|推荐|放|播放|来|换|切换)(?:一|下|个|首|点|这|那|别的|其他|另一|下一|歌曲|音乐){0,8}(?:歌|歌曲|音乐|首)|(?:我想听|我要听|想听听|播放|切到|换成).{0,40}/.test(value);}
  function parseCompanionSongChoice(reply){const text=String(reply||''),structured=text.match(/(?:选择|播放)[：:]\s*《?([^\n|｜》]+)》?\s*[|｜]\s*([^\n]+)/i);if(structured)return{title:structured[1].trim(),artist:structured[2].trim()};const quoted=text.match(/([A-Za-z0-9\u4e00-\u9fff .·&]{1,50})\s*(?:的)?《([^》]{1,100})》/);if(quoted)return{title:quoted[2].trim(),artist:quoted[1].replace(/^(?:那就|想听|听听|试试|播放|来一首|可以听)\s*/,'').trim()};return null;}
  function visibleCompanionSongReply(reply){return String(reply||'').replace(/\n?\s*(?:选择|播放)[：:]\s*《?[^\n|｜》]+》?\s*[|｜]\s*[^\n]+\s*$/i,'').trim()||'这首吧。';}
  function companionLatestRoundText(info=companionCharacter()){const main=(info.ctx?.chat||[]).filter(message=>message&&!message.is_system&&String(message.mes||'').trim()).slice(-2).map(message=>`${message.is_user?String(info.ctx?.name1||'用户'):info.name}：${String(message.mes).slice(0,900)}`),privateChat=companionMessages(info).slice(-2).map(message=>`${message.role==='assistant'?info.name:String(info.ctx?.name1||'用户')}：${String(message.content||'').slice(0,900)}`);return[...main,...privateChat].join('\n')||'刚刚打开陪听窗，还没有新的对话。';}
  function companionRecommendationTask({mood='',userText='',authorized=false}={}){const info=companionCharacter(),latest=companionLatestRoundText(info),playing=current?`《${current.title}》 | ${current.artist}`:'无';return`请进行一次全网点歌推荐。不要局限于用户收藏、“我们的歌”或已导入歌单。请综合以下依据：当前角色心情“${companionMood(info)}”；角色卡的人设、经历、偏好和关系；系统提示中本轮实际激活的世界书；最新一轮对话；当前歌曲。\n${mood?`用户主动选择的心情：${mood}\n`:''}${userText?`用户原话：${String(userText).slice(0,600)}\n`:''}最新一轮对话：\n${latest}\n当前歌曲：${playing}\n\n默认尽量推荐欧美音乐，优先真实存在的英文歌曲和欧美歌手。角色设定、用户明确指定的歌名歌手或当前剧情明显指向其他语言时，以这些信息优先。若用户指定了歌曲，请严格按指定内容选择；若是换歌，请避开当前歌曲。只选择确实发行过、可搜索的歌曲，不得虚构歌名或歌手。像真人聊天一样先用一两句短话回应，不写动作描写，不解释分析过程。最后必须另起一行准确输出：选择：官方歌名 | 歌手。${authorized?'用户已经授权本次播放，选定后将直接搜索并播放。':'这一步只提出推荐，最终是否播放由用户确认。'}`;}
  async function searchCompanionChoice(choice){if(!choice?.title)return null;const before=current?offlineKey(current):'',titleKey=normalizeSongText(choice.title),artistKey=normalizeSongText(choice.artist||'');await search(`${choice.title} ${choice.artist||''}`.trim(),false,false);const ranked=results.map(song=>{const title=normalizeSongText(song.title),artist=normalizeSongText(song.artist),score=(title===titleKey?12:title.includes(titleKey)||titleKey.includes(title)?7:0)+(artistKey&&(artist===artistKey?8:artist.includes(artistKey)||artistKey.includes(artist)?4:0))-(before&&offlineKey(song)===before?20:0);return{song,score};}).sort((a,b)=>b.score-a.score),song=ranked[0]?.score>0?ranked[0].song:results.find(item=>!before||offlineKey(item)!==before)||results[0]||null;if(song)await play(song);return song;}
  async function fulfillCompanionSongRequest(userText){const reply=await runCompanionTask(companionRecommendationTask({userText,authorized:true}));if(!reply)return false;const info=companionCharacter(),display=visibleCompanionSongReply(reply),messages=companionMessages(info);messages.push({role:'assistant',content:display.slice(0,1600),time:Date.now()});setCompanionMessages(messages,info);save();await speakCompanionReply(display,info);const choice=parseCompanionSongChoice(reply),song=await searchCompanionChoice(choice);if(song)markCompanionPicked(song);else toast('warning','角色选了歌，但暂时没有搜索到可播放音源');renderCompanionDialog();return true;}
  async function askCompanionToPick(mood=''){const reply=await runCompanionTask(companionRecommendationTask({mood}));if(!reply)return;const choice=parseCompanionSongChoice(reply);if(!choice?.title){toast('warning','角色没有返回可搜索的歌名和歌手');return;}const display=visibleCompanionSongReply(reply);if(!ROOT.confirm?.(`${companionCharacter().name} 想推荐：\n《${choice.title}》 | ${choice.artist}\n\n${display}\n\n全网搜索并播放吗？`))return;const info=companionCharacter(),messages=companionMessages(info);messages.push({role:'assistant',content:display.slice(0,1600),time:Date.now()});setCompanionMessages(messages,info);save();const song=await searchCompanionChoice(choice);if(song)markCompanionPicked(song);else toast('warning','暂时没有搜索到这首歌的可播放音源');renderCompanionDialog();}
  function showMoodPicker(){const moods=['开心','失眠','想念','治愈','浪漫','战斗','雨天','安静'];openCompanionFeature('☾ 心情匹配',`<p>现在是什么心情？角色会结合人设和最新对话，从全网尽量挑一首欧美歌曲。</p><div class="mood-grid">${moods.map(m=>`<button data-mood="${m}">${m}</button>`).join('')}</div>`,e=>{const mood=e.target.closest('[data-mood]')?.dataset.mood;if(mood){DOC.querySelector(`#${ID}-companion .companion-feature`).hidden=true;askCompanionToPick(mood);}});}
