    const endAvatar=e=>{if(!avatarDrag||e?.pointerId!==undefined&&avatarDrag.id!==e.pointerId)return;const moved=avatarDrag.moved;try{avatar.releasePointerCapture?.(avatarDrag.id);}catch{}avatarDrag=null;if(moved)persistCompanionPosition(dialog,true);ROOT.setTimeout(()=>{companionDragged=false;},0);};avatar.onpointerup=endAvatar;avatar.onpointercancel=endAvatar;avatar.onlostpointercapture=endAvatar;
